// Helper to parse hex color to rgb
const hexToRgb = (hex: string) => {
  const r = parseInt(hex.slice(1, 3), 16) || 255;
  const g = parseInt(hex.slice(3, 5), 16) || 42;
  const b = parseInt(hex.slice(5, 7), 16) || 20;
  return { r, g, b };
};

// Procedural Brick Wall Component for authentic physical background
const BrickWall: React.FC<{ color: string }> = ({ color }) => {
  const { width, height } = useVideoConfig();
  const { r: br, g: bg, b: bb } = hexToRgb(color);

  // Set brick grid spacing
  const rowHeight = 64;
  const brickWidth = 160;
  const numRows = Math.ceil(height / rowHeight) + 1;
  const numBricks = Math.ceil(width / brickWidth) + 2;

  const rows = [];
  for (let r = 0; r < numRows; r++) {
    const offset = (r % 2) * (brickWidth / 2) - brickWidth;
    const rowBricks = [];
    for (let b = 0; b < numBricks; b++) {
      const seed = `brick-${r}-${b}`;
      
      // Generate realistic brick color variations
      const varR = Math.floor(random(`${seed}-r`) * 16 - 8);
      const varG = Math.floor(random(`${seed}-g`) * 10 - 5);
      const varB = Math.floor(random(`${seed}-b`) * 10 - 5);
      
      const brickColor = `rgb(${Math.max(0, br + varR)}, ${Math.max(0, bg + varG)}, ${Math.max(0, bb + varB)})`;
      
      rowBricks.push({
        id: `${r}-${b}`,
        x: b * brickWidth + offset,
        y: r * rowHeight,
        w: brickWidth - 6, // 6px grout line gap
        h: rowHeight - 6,
        color: brickColor,
        opacity: 0.85 + random(`${seed}-op`) * 0.15,
      });
    }
    rows.push(rowBricks);
  }

  return (
    <svg
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: "100%",
        height: "100%",
        backgroundColor: "#070404", // Dark grout / mortar background
        transition: "none",
      }}
    >
      {rows.map((rowBricks) =>
        rowBricks.map((brick) => (
          <rect
            key={brick.id}
            x={brick.x}
            y={brick.y}
            width={brick.w}
            height={brick.h}
            fill={brick.color}
            opacity={brick.opacity}
            rx={4}
            ry={4}
            style={{ transition: "none" }}
          />
        ))
      )}
    </svg>
  );
};

